/*
  Slovar vrednosti — zacetna polnitev iz "Prevajalna tabela.xlsx", list "Besede"
  (2.923 vrstic, stolpci SLOVENSCINA / ANGLESCINA / NEMSCINA / HRVASCINA).

  NI migracija. To so podatki, ne shema, zato se ne izvede sam na vsakem okolju.
  Zaganja se rocno in je idempotenten: pise samo tja, kjer para se ni, obstojecih
  vrednosti nikoli ne prepise.

  Vir vrednosti je izkljucno preglednica; nobena vrednost ni izmisljena ali prevedena
  strojno. Vpisanih je 6.316 vrstic iz 2.555 razlicnih angleskih vrednosti:
  2317 slovenskih, 2075 nemskih in 1924 hrvaskih parov.

  Kaj je izpusceno in zakaj: 236 angleskih besed ima v preglednici vec razlicnih
  slovenskih prevodov, npr. "black" -> crn / crna / crne / crni / crno in
  "antique" -> Anticna / Anticni / (antique); enako velja za 75 nemskih in 126
  hrvaskih. To ni napaka preglednice, ampak
  posledica sklanjatve: pravilen prevod je odvisen od lastnosti, ob kateri stoji.
  Takih parov skript ne vpise, ker bi izbira med njimi bila ugibanje. Zbrani so v
  docs\Prevodi_sporni.csv; ko bo za vsakega znana lastnost, dobijo vrstico z
  Domain = koda lastnosti namesto '*'.

  Vsi vpisi imajo Domain = '*' (velja povsod). Ozja domena jih premaga, zato
  kasnejsi natancnejsi vpis tega ne pokvari.
*/


/* map.ValueLookup ima iskalni kljuc kot izracunan stolpec z indeksom, zato zahteva
   QUOTED_IDENTIFIER ON. SqlClient in SSMS to nastavita sama, sqlcmd ne — brez te
   vrstice INSERT pade z napako 1934. */
SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;

