WHERE NOT EXISTS
(
  SELECT 1 FROM map.ValueLookup existing
  WHERE existing.Domain = N'*' AND existing.SourceValue = source.SourceValue
    AND existing.Language = source.Language
);

SELECT Language, COUNT(*) AS Vrstic FROM map.ValueLookup WHERE Domain = N'*' GROUP BY Language ORDER BY Language;
